{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": {
    "allow_fallbacks": true
  },
  "messages": [
    {
      "role": "system",
      "content": "You are a booking assistant. Extract booking details from the customer message and return ONLY a valid JSON object with these fields: preferred_date (YYYY-MM-DD or null), preferred_time (HH:MM in 24h format or null), service_type (string describing what service they want or null). Do not include any explanation or markdown, only the JSON object."
    },
    {
      "role": "user",
      "content": "{{1.body.messages[0].text}}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 256
}

{
  "actor_type": "agent",
  "actor_id": "{{env.FRESHCHAT_BOT_ID}}",
  "message_type": "normal",
  "message_parts": [
    {
      "text": {
        "content": "I'm sorry, {{1.body.actors[0].first_name}}! We encountered a technical issue while processing your booking request. Our team has been notified and will reach out to you shortly to complete your appointment. In the meantime, you can grab any open time instantly here: {{env.CALENDLY_BOOKING_LINK}}"
